CAT = "ea2Retirement"; SEG = "RET"
# Retirement plans, farmers and rental property.
Q = [
("An employer's SEP contribution for an employee may not exceed the smaller of an indexed dollar limit or what share of compensation?",
 "25%", ["15%", "20%", "100%"],
 "Publication 560 caps SEP contributions at the smaller of 25% of the employee's compensation or the year's dollar limit. For a self-employed owner the 25% works out to 20% of net earnings."),
("For 2025, a self-employed person may set up and fund a SEP as late as:",
 "Its extended return due date", ["Its original return due date", "December 31, 2025", "October 1, 2025"],
 "Publication 560 allows a SEP to be set up for a year as late as the due date, including extensions, of the employer's return for that year, with contributions made by the same date."),
("A business that has never had a SIMPLE IRA plan wants one for 2025. It must generally set the plan up by:",
 "October 1, 2025", ["December 31, 2025", "April 15, 2026", "July 1, 2025"],
 "Publication 560 says a new SIMPLE IRA plan may be set up any time between January 1 and October 1 of the year. A new employer that comes into existence after October 1 may set one up as soon as possible."),
("Under a SIMPLE IRA plan, an employer that matches elective deferrals must generally match dollar for dollar up to:",
 "3% of compensation", ["6% of compensation", "2% of compensation", "5% of compensation"],
 "The SIMPLE IRA match is up to 3% of compensation, reducible to 1% in 2 of 5 years. The alternative is a 2% nonelective contribution for every eligible employee, not a 2% match."),
("A 45-year-old withdraws from a SIMPLE IRA 18 months after first joining the plan, and no exception applies. The additional tax is:",
 "25%", ["10%", "20%", "50%"],
 "Section 72(t)(6) raises the 10% additional tax to 25% for SIMPLE IRA distributions within 2 years after the employee first participated, unless an exception applies."),
("A disqualified person engages in a prohibited transaction with a plan. The first-tier excise tax is:",
 "15% of the amount involved", ["10% of the amount involved", "25% of the amount involved", "100% of the amount involved"],
 "Section 4975(a) imposes a 15% first-tier tax for each year in the taxable period. A 100% second-tier tax applies if the transaction is not corrected."),
("A one-participant 401(k) plan covering only the owner must file Form 5500-EZ when year-end plan assets are:",
 "More than $250,000", ["More than $100,000", "More than $500,000", "Any amount at all"],
 "Publication 560 excuses a one-participant plan from Form 5500-EZ for a year when total assets were $250,000 or less, except for its final plan year."),
("An employer deducts compensation paid under a nonqualified deferred compensation plan:",
 "When the employee includes it", ["When the promise is made", "When it funds a rabbi trust", "Evenly over the vesting period"],
 "Section 404(a)(5) delays the employer's deduction until the year the amount is includible in the employee's income, matching the deduction to the inclusion."),
("A cash-method farmer who usually sells a crop the year after harvest receives 2025 crop insurance proceeds for drought damage. The farmer may elect to:",
 "Report them in 2026", ["Exclude them from income", "Spread them over 3 years", "Report them over 2 years"],
 "Section 451(f) and Publication 225 let a cash-method farmer postpone crop insurance and disaster payments to the following year if under normal practice the crop would have been sold then."),
("Breeding cattle sold by a farmer qualify as section 1231 property if they were held:",
 "24 months or more", ["12 months or more", "6 months or more", "36 months or more"],
 "Publication 225 treats livestock held for draft, breeding, dairy or sport as section 1231 property after 12 months, or 24 months for cattle and horses."),
("A farmer sells more livestock than usual because of drought in a designated area. The gain can be deferred if replacement livestock is bought within:",
 "4 years", ["2 years", "1 year", "3 years"],
 "Section 1033(e)(2) extends the replacement period to 4 years for livestock sold on account of drought, flood or other weather conditions in an applicable region, and longer while the region stays drought-listed."),
("Form 4835 is used by:",
 "A landowner who does not materially participate", ["A tenant farmer who works the land", "A landowner who materially participates", "A cooperative paying patronage dividends"],
 "Form 4835 reports crop or livestock shares received as rent by a landowner who did not materially participate in the farming. That income is not subject to self-employment tax and goes to Schedule E."),
("Schedule J (Form 1040) lets a farmer:",
 "Average farm income over 3 prior years", ["Average it over 5 prior years", "Defer it over the next 3 years", "Exclude part of it up to a cap"],
 "Farm income averaging taxes elected farm income at the rates of the 3 prior base years, which can lower the tax in a high-income year. It does not defer or exclude the income."),
("Cash patronage dividends a farmer receives from a cooperative based on purchases of deducted farm supplies are:",
 "Included in farm income", ["Excluded as price rebates", "Taxed as capital gains", "Exempt like interest"],
 "Publication 225 includes patronage dividends from purchases of business supplies in farm income, since the supplies were deducted. Dividends from personal purchases would instead reduce cost."),
("A building is residential rental property for MACRS only if dwelling units produce at least what share of its gross rents?",
 "80%", ["50%", "75%", "90%"],
 "Section 168(e)(2)(A) and Publication 527 require 80% or more of gross rental income from dwelling units. A building that falls short is nonresidential real property with a 39-year life."),
("A homeowner rents her residence for 12 days in 2025 and lives in it the rest of the year. The rent is:",
 "Not reported at all", ["Fully taxable", "Taxable after expenses", "Taxable above $1,000"],
 "Section 280A(g) excludes rent when a dwelling used as a home is rented fewer than 15 days in the year, and no rental expenses are deducted."),
("A vacation home is treated as a residence if personal use exceeds the greater of:",
 "14 days or 10% of days rented", ["14 days or 10% of the year", "30 days or 10% of days rented", "14 days or 15% of days rented"],
 "Section 280A(d)(1) treats a dwelling as a residence when personal use is more than the greater of 14 days or 10% of the days it is rented at fair rent, and then limits rental deductions to rental income."),
("A landlord collects a refundable security deposit at signing. The deposit is:",
 "Not income when received", ["Income when it is received", "Income when the lease starts", "Income spread over the lease"],
 "Publication 527 excludes a security deposit the landlord plans to return. It becomes income only when kept, for example for damage or unpaid rent."),
("A tenant pays the last month's rent at signing in 2025 for a lease ending in 2027. The landlord reports it:",
 "In 2025, when received", ["In 2027, the month it covers", "Only once the lease ends", "Over the lease term"],
 "Publication 527 treats advance rent as income when received, whatever period it covers and whatever accounting method the landlord uses."),
("A real estate professional who owns six rentals must materially participate in each one unless she:",
 "Elects to group them as one activity", ["Owns fewer than ten rental units", "Hires a property manager for all", "Has MAGI under $150,000 that year"],
 "Section 469(c)(7)(A) applies rental by rental unless the taxpayer elects to treat all interests in rental real estate as a single activity, which makes material participation easier to meet."),
]
